package com.shop.order.domain;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

@Entity
@Table(name = "orders")
public class Order {

    public enum Status { PENDING, CONFIRMED, CANCELLED, SHIPPED }

    @Id
    private UUID id = UUID.randomUUID();

    // reference to another bounded context by identifier only, never by @ManyToOne
    @Column(nullable = false)
    private UUID customerId;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private Status status = Status.PENDING;

    @Column(nullable = false, precision = 12, scale = 2)
    private BigDecimal total = BigDecimal.ZERO;

    @Column(nullable = false)
    private Instant createdAt = Instant.now();

    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true)
    @JoinColumn(name = "order_id")
    private List<OrderLine> lines = new ArrayList<>();

    @Version
    private long version;

    protected Order() { }
    public Order(UUID customerId) {
        this.customerId = customerId;
    }

    public void addLine(String sku, int quantity, BigDecimal unitPrice) {
        lines.add(new OrderLine(sku, quantity, unitPrice));
        total = total.add(unitPrice.multiply(BigDecimal.valueOf(quantity)));
    }

    public void confirm() {
        if (status != Status.PENDING) {
            throw new IllegalStateException("Order " + id + " is " + status);
        }
        status = Status.CONFIRMED;
    }

    public void cancel() {
        if (status == Status.SHIPPED) {
            throw new IllegalStateException("Shipped order cannot be cancelled");
        }
        status = Status.CANCELLED;
    }

    public UUID getId() { return id; }
    public UUID getCustomerId() { return customerId; }
    public Status getStatus() { return status; }
    public BigDecimal getTotal() { return total; }
    public List<OrderLine> getLines() { return List.copyOf(lines); }
}

