package com.shop.order.application;

import com.shop.order.domain.Order;
import com.shop.order.domain.OrderRepository;
import java.math.BigDecimal;
import java.util.List;
import java.util.UUID;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderService {

    public record Item(String sku, int quantity) { }

    private final OrderRepository orders;
    // ports implemented by HTTP clients to catalog-service and inventory-service
    private final PriceLookup prices;
    private final StockReservation stock;

    public OrderService(OrderRepository orders, PriceLookup prices, StockReservation stock) {
        this.orders = orders;
        this.prices = prices;
        this.stock = stock;
    }

    @Transactional
    public Order place(UUID customerId, List<Item> items) {
        Order order = new Order(customerId);
        for (Item item : items) {
            BigDecimal price = prices.priceOf(item.sku());
            order.addLine(item.sku(), item.quantity(), price);
        }
        orders.save(order);
        // remote call inside a local transaction: see the chapters on resilience and sagas
        stock.reserve(order.getId(), items);
        return order;
    }
}

public class AvailabilityMath {

    public static void main(String[] args) {
        System.out.println("Serial chain: every service must be up for a request to succeed");
        System.out.printf("%-10s %-14s %-14s %s%n", "services", "each 99.9%", "each 99.99%",
                "downtime/month at 99.9% each");
        for (int n : new int[] {1, 3, 5, 10, 20}) {
            double a = Math.pow(0.999, n), b = Math.pow(0.9999, n);
            System.out.printf("%-10d %-14.4f %-14.4f %.0f minutes%n", n, a * 100, b * 100,
                    (1 - a) * 30 * 24 * 60);
        }
        System.out.println();
        System.out.println(
                "Tail latency: fraction of user requests that see at least one slow (p99) call");
        System.out.printf("%-12s %s%n", "fan-out", "P(at least one call slower than its p99)");
        for (int n : new int[] {1, 5, 10, 50, 100}) {
            System.out.printf("%-12d %.1f%%%n", n, (1 - Math.pow(0.99, n)) * 100);
        }
    }
}

