package com.shop.order.infrastructure;

import org.apache.hc.client5.http.config.ConnectionConfig;
import org.apache.hc.client5.http.config.RequestConfig;
import org.apache.hc.client5.http.impl.classic.CloseableHttpClient;
import org.apache.hc.client5.http.impl.classic.HttpClients;
import org.apache.hc.client5.http.impl.io.PoolingHttpClientConnectionManager;
import org.apache.hc.client5.http.impl.io.PoolingHttpClientConnectionManagerBuilder;
import org.apache.hc.core5.util.TimeValue;
import org.apache.hc.core5.util.Timeout;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.client.HttpComponentsClientHttpRequestFactory;
import org.springframework.web.client.RestClient;
import org.springframework.web.client.support.RestClientAdapter;
import org.springframework.web.service.invoker.HttpServiceProxyFactory;

@Configuration(proxyBeanMethods = false)
class InventoryClientConfig {

    @Bean
    RestClient inventoryRestClient(RestClient.Builder builder,
                                   @Value("${clients.inventory.base-url}") String baseUrl) {
        PoolingHttpClientConnectionManager pool = PoolingHttpClientConnectionManagerBuilder.create()
            .setMaxConnTotal(50)
            .setMaxConnPerRoute(25)
            .setDefaultConnectionConfig(ConnectionConfig.custom()
                .setConnectTimeout(Timeout.ofMillis(300))      // phase 2
                .setSocketTimeout(Timeout.ofMillis(800))       // phase 3 and 4, per read
                .build())
            .build();
        CloseableHttpClient http = HttpClients.custom()
            .setConnectionManager(pool)
            .setDefaultRequestConfig(RequestConfig.custom()
                .setConnectionRequestTimeout(Timeout.ofMillis(200))   // phase 1
                .setResponseTimeout(Timeout.ofMillis(800))
                .build())
            .evictExpiredConnections()
            .evictIdleConnections(TimeValue.ofSeconds(30))
            .build();
        return builder.baseUrl(baseUrl)
            .requestFactory(new HttpComponentsClientHttpRequestFactory(http))
            .defaultStatusHandler(status -> status.is5xxServerError(), (request, response) -> {
                int code = response.getStatusCode().value();
                throw new DependencyUnavailableException("inventory", code);
            })
            .build();
    }

    @Bean
    InventoryClient inventoryClient(RestClient inventoryRestClient) {
        return HttpServiceProxyFactory
            .builderFor(RestClientAdapter.create(inventoryRestClient))
            .build()
            .createClient(InventoryClient.class);
    }
}

