package com.shop.payment.idempotency;

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface IdempotencyRepository extends JpaRepository<IdempotencyRecord, String> {

    /** Returns 1 if this call claimed the key, 0 if the key already existed. */
    @Modifying
    @Query(value = """
        INSERT INTO idempotency_key (key, request_hash, created_at)
        VALUES (:key, :hash, now())
        ON CONFLICT (key) DO NOTHING
        """, nativeQuery = true)
    int claim(@Param("key") String key, @Param("hash") String hash);
}

package com.shop.payment;

import com.shop.payment.idempotency.IdempotencyRecord;
import com.shop.payment.idempotency.IdempotencyRepository;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.HexFormat;
import java.util.Map;
import java.util.UUID;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class PaymentService {

    public record CaptureRequest(UUID orderId, BigDecimal amount, String currency) { }

    private final IdempotencyRepository keys;
    private final PaymentRepository payments;

    public PaymentService(IdempotencyRepository keys, PaymentRepository payments) {
        this.keys = keys;
        this.payments = payments;
    }

    @Transactional
    public ResponseEntity<Map<String, Object>> capture(String key, CaptureRequest request) {
        String hash = sha256(request.orderId() + "|" + request.amount() + "|" + request.currency());
        if (keys.claim(key, hash) == 0) {
            IdempotencyRecord stored = keys.findById(key).orElseThrow();
            if (!stored.getRequestHash().equals(hash)) {
                throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
                    "Idempotency-Key reused with a different request");
            }
            return ResponseEntity.status(stored.getResponseCode()).body(stored.getResponseBody());
        }
        Payment payment = payments.save(
            new Payment(request.orderId(), request.amount(), "CAPTURED"));
        Map<String, Object> body =
            Map.of("paymentId", payment.getId(), "state", payment.getState());
        keys.findById(key).orElseThrow().complete(HttpStatus.CREATED.value(), body);
        return ResponseEntity.status(HttpStatus.CREATED).body(body);
    }

    private static String sha256(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                .digest(value.getBytes(StandardCharsets.UTF_8));
            return HexFormat.of().formatHex(digest);
        } catch (java.security.NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }
}

import com.sun.net.httpserver.HttpServer;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.*;

public class DistributedNPlusOne {

    static final AtomicInteger requests = new AtomicInteger();

    public static void main(String[] args) throws Exception {
        // avoid Nagle/delayed-ACK stalls
        System.setProperty("sun.net.httpserver.nodelay", "true");
        // "customer-service": 5 ms of work per request, regardless of batch size
        HttpServer srv = HttpServer.create(new InetSocketAddress("127.0.0.1", 21420), 0);
        srv.setExecutor(Executors.newFixedThreadPool(16));
        srv.createContext("/customers", ex -> {
            requests.incrementAndGet();
            try { Thread.sleep(5); } catch (InterruptedException e) { }
            String q = ex.getRequestURI().getQuery();
            String body = q == null ? "{\"id\":" + ex.getRequestURI().getPath().replaceAll("\\D",
                    "") + "}"
                    : "[" + Arrays.stream(q.substring(4).split(",")).map(i -> "{\"id\":" + i + "}")
                            .collect(Collectors.joining(",")) + "]";
            byte[] b = body.getBytes();
            ex.sendResponseHeaders(200, b.length);
            ex.getResponseBody().write(b); ex.close();
        });
        srv.start();

        HttpClient http = HttpClient.newBuilder().version(HttpClient.Version.HTTP_1_1).build();
        // 50 orders, 50 customers
        List<Integer> customerIds = IntStream.rangeClosed(1, 50).boxed().toList();
        http.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:21420/customers/1")).build(),
                HttpResponse.BodyHandlers.ofString());                                    // warm-up
        requests.set(0);

        long t = System.nanoTime();
        for (int id : customerIds)
            http.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:21420/customers/"
                    + id)).build(),
                    HttpResponse.BodyHandlers.ofString());
        report("1. one call per order, sequential", t);

        requests.set(0); t = System.nanoTime();
        try (var vt = Executors.newVirtualThreadPerTaskExecutor()) {
            List<Future<String>> fs = new ArrayList<>();
            for (int id : customerIds) fs.add(vt.submit(() -> http.send(
                    HttpRequest.newBuilder(URI.create("http://127.0.0.1:21420/customers/"
                            + id)).build(),
                    HttpResponse.BodyHandlers.ofString()).body()));
            for (var f : fs) f.get();
        }
        report("2. one call per order, parallel (virtual threads)", t);
        requests.set(0); t = System.nanoTime();
        String ids = customerIds.stream().map(String::valueOf).collect(Collectors.joining(","));
        http.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:21420/customers?ids="
                + ids)).build(),
                HttpResponse.BodyHandlers.ofString());
        report("3. one batch call /customers?ids=1,2,...,50", t);
        srv.stop(0);
        System.exit(0);
    }

    static void report(String what, long t0) {
        System.out.printf("%-52s requests=%2d  elapsed=%4d ms%n", what, requests.get(),
                (System.nanoTime() - t0) / 1_000_000);
    }
}

public Page<OrderSummary> list(Pageable pageable) {
    Page<Order> page = orders.findAll(pageable);
    Set<UUID> ids = page.stream().map(Order::getCustomerId).collect(Collectors.toSet());
    Map<UUID, String> names = customers.byIds(ids).stream()
        .collect(Collectors.toMap(CustomerSummary::id, CustomerSummary::name));
    return page.map(o -> new OrderSummary(o.getId(), o.getStatus(),
        names.getOrDefault(o.getCustomerId(), "unknown")));
}

package com.shop.gateway;

import java.util.Optional;
import org.springframework.cloud.gateway.filter.ratelimit.KeyResolver;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import reactor.core.publisher.Mono;

@Configuration(proxyBeanMethods = false)
class GatewayConfig {

    /** Rate-limit key: the client id header when present, otherwise the remote address. */
    @Bean
    KeyResolver clientKeyResolver() {
        return exchange -> {
            String clientId = exchange.getRequest().getHeaders().getFirst("X-Client-Id");
            if (clientId != null && !clientId.isBlank()) {
                return Mono.just(clientId);
            }
            return Mono.just(Optional.ofNullable(exchange.getRequest().getRemoteAddress())
                .map(address -> address.getAddress().getHostAddress())
                .orElse("unknown"));
        };
    }
}

package com.shop.gateway;

import java.util.UUID;
import org.springframework.cloud.gateway.filter.GatewayFilterChain;
import org.springframework.cloud.gateway.filter.GlobalFilter;
import org.springframework.core.Ordered;
import org.springframework.http.server.reactive.ServerHttpRequest;
import org.springframework.stereotype.Component;
import org.springframework.web.server.ServerWebExchange;
import reactor.core.publisher.Mono;

@Component
public class RequestIdFilter implements GlobalFilter, Ordered {

    public static final String HEADER = "X-Request-Id";

    @Override
    public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
        String id = exchange.getRequest().getHeaders().getFirst(HEADER);
        if (id == null || id.isBlank()) {
            id = UUID.randomUUID().toString();
        }
        ServerHttpRequest request = exchange.getRequest().mutate().header(HEADER, id).build();
        exchange.getResponse().getHeaders().set(HEADER, id);
        return chain.filter(exchange.mutate().request(request).build());
    }

    @Override
    public int getOrder() {
        return Ordered.HIGHEST_PRECEDENCE;     // first in the pre phase, last in the post phase
    }
}

