import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class MiniGateway {

    record Instance(String id, int port) {}

    /** Route = Path predicate + StripPrefix filter + client-side round-robin over instances. */
    static class Route {
        final String id, prefix;
        final List<Instance> instances;
        final AtomicInteger next = new AtomicInteger();
        final Map<String, Long> downUntil = new ConcurrentHashMap<>();
    Route(String id, String prefix, List<Instance> instances) {
        this.id = id;
        this.prefix = prefix;
        this.instances = instances;
    }

    boolean matches(String path) { return path.startsWith(prefix); }
    Optional<Instance> choose(Set<String> tried) {
        long now = System.currentTimeMillis();
        for (int i = 0; i < instances.size(); i++) {
            Instance c = instances.get(Math.floorMod(next.getAndIncrement(), instances.size()));
            if (tried.contains(c.id()) || downUntil.getOrDefault(c.id(), 0L) > now) continue;
            return Optional.of(c);
        }
        return Optional.empty();
    }
}

/** Token bucket: capacity 5, refilled at 5 tokens per second, keyed by client. */
static class Bucket {
    double tokens = 5; long last = System.nanoTime();
    synchronized boolean take() {
        long n = System.nanoTime();
        tokens = Math.min(5, tokens + (n - last) / 1e9 * 5); last = n;
        if (tokens >= 1) { tokens -= 1; return true; }
        return false;
    }
}

static HttpServer backend(String id, int port) throws IOException {
    HttpServer s = HttpServer.create(new InetSocketAddress("127.0.0.1", port), 0);
    s.createContext("/", ex -> {
        String body = "{\"instance\":\"" + id + "\",\"path\":\"" + ex.getRequestURI()
                + "\",\"requestId\":\""
                + ex.getRequestHeaders().getFirst("X-Request-Id") + "\"}";
        reply(ex, 200, body);
    });
    s.start();
    return s;
}

static void reply(HttpExchange ex, int code, String body) throws IOException {
    byte[] b = body.getBytes(StandardCharsets.UTF_8);
    ex.getResponseHeaders().add("Content-Type", "application/json");
    ex.sendResponseHeaders(code, b.length);
    try (var os = ex.getResponseBody()) { os.write(b); }
}

public static void main(String[] args) throws Exception {
    HttpServer o1 = backend("order-1", 21401), o2 = backend("order-2", 21402),
            o3 = backend("order-3", 21403);
    HttpServer u1 = backend("user-1", 21404);
    List<Route> routes = List.of(
            new Route("orders", "/api/orders", List.of(new Instance("order-1", 21401),
                    new Instance("order-2", 21402), new Instance("order-3", 21403))),
            new Route("users", "/api/users", List.of(new Instance("user-1", 21404))));
    Map<String, Bucket> buckets = new ConcurrentHashMap<>();
    HttpClient http = HttpClient.newBuilder().connectTimeout(Duration.ofMillis(300)).build();
    AtomicInteger ids = new AtomicInteger(1000);

    HttpServer gw = HttpServer.create(new InetSocketAddress("127.0.0.1", 21410), 0);
    gw.createContext("/", ex -> {
        String client = ex.getRequestHeaders().getFirst("X-Client");
        if (client != null && !buckets.computeIfAbsent(client, k -> new Bucket()).take()) {
            reply(ex, 429, "{\"error\":\"rate limit exceeded\"}"); return;
        }
        String path = ex.getRequestURI().getPath();
        Route r = routes.stream().filter(x -> x.matches(path)).findFirst().orElse(null);
        if (r == null) { reply(ex, 404, "{\"error\":\"no route\"}"); return; }
        String stripped = path.substring("/api".length());       // StripPrefix=1
        Set<String> tried = new HashSet<>();
        for (int attempt = 0; attempt < 3; attempt++) {
            Optional<Instance> inst = r.choose(tried);
            if (inst.isEmpty()) break;
                tried.add(inst.get().id());
                try {
                    HttpRequest req = HttpRequest.newBuilder(URI.create("http://127.0.0.1:"
                            + inst.get().port() + stripped))
                            .timeout(Duration.ofSeconds(1)).header("X-Request-Id", "req-"
                                    + ids.incrementAndGet()).GET().build();
                    HttpResponse<String> resp = http.send(req,
                            HttpResponse.BodyHandlers.ofString());
                    reply(ex, resp.statusCode(), resp.body());
                    return;
                } catch (IOException | InterruptedException e) {
                    r.downUntil.put(inst.get().id(), System.currentTimeMillis() + 2000);
                    System.out.println("  gateway: " + inst.get().id() + " failed ("
                            + e.getClass().getSimpleName()
                            + "), marked down for 2 s, trying next");
                }
            }
            reply(ex, 503, "{\"error\":\"no healthy instance for route " + r.id + "\"}");
        });
        gw.start();

        HttpClient c = HttpClient.newHttpClient();
        String[] last = new String[1];
