import java.util.List;
import java.util.UUID;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;

@Component
public class InventoryGateway implements StockReservation {

    private static final Logger log = LoggerFactory.getLogger(InventoryGateway.class);

    private final InventoryClient client;

    public InventoryGateway(InventoryClient client) {
        this.client = client;
    }

    @Bulkhead(name = "inventory")
    @CircuitBreaker(name = "inventory")
    @Retry(name = "inventory", fallbackMethod = "reservationUnavailable")
    @Override
    public void reserve(UUID orderId, List<OrderService.Item> items) {
        List<InventoryClient.Line> lines = items.stream()
            .map(i -> new InventoryClient.Line(i.sku(), i.quantity()))
            .toList();
        // the order id is the idempotency key: every retry of this reservation carries the same key
        client.reserve(orderId.toString(), new InventoryClient.ReservationRequest(orderId, lines));
    }

    /** Fallback: the failure is translated into a domain exception, not hidden. */
    void reservationUnavailable(UUID orderId, List<OrderService.Item> items, Throwable cause) {
        log.warn("Stock reservation for order {} unavailable: {}", orderId, cause.toString());
        throw new StockUnavailableException(orderId, cause);
    }
}

