import java.util.Random;
import java.util.TreeMap;
import java.util.Map;

public class RetryDemo {

    static int downstreamCalls;

    /** One layer calls the next and retries on failure; the innermost dependency always fails. */
    static boolean call(int layer, int[] attempts) {
        if (layer == attempts.length) { downstreamCalls++; return false; }
        for (int i = 0; i < attempts[layer]; i++) {
            if (call(layer + 1, attempts)) return true;
        }
        return false;
    }
    static void backoff() {
        System.out.println("== backoff schedule (base 100 ms, multiplier 2, 5 attempts, seed 42)");
        Random r = new Random(42);
        long delay = 100;
        for (int attempt = 1; attempt <= 4; attempt++) {
            long full = (long) (r.nextDouble() * delay);
            long equal = delay / 2 + (long) (r.nextDouble() * delay / 2);
            System.out.printf(
                    "after failure %d: exponential=%4d  full-jitter=%4d  equal-jitter=%4d (ms)%n",
                    attempt, delay, full, equal);
            delay *= 2;
        }
        System.out.println();
    }

    static void storm() {
        System.out.println("== retry amplification when the innermost dependency is down");
        int[][] cfgs = {{3, 3, 3}, {3, 3, 1}, {1, 1, 3}};
        String[] names = {"gateway=3 order=3 inventory-client=3",
                "gateway=3 order=3 inventory-client=1",
                "gateway=1 order=1 inventory-client=3"};
        for (int i = 0; i < cfgs.length; i++) {
            downstreamCalls = 0;
            call(0, cfgs[i]);
            System.out.printf("%-42s -> %2d calls reach the failing dependency per user request%n",
                    names[i], downstreamCalls);
        }
        System.out.println();
    }

    static void herd() {
        System.out.println("== 1000 clients fail at t=0 and retry; arrivals per 250 ms bucket");
        String[] modes = {"fixed 1000 ms, no jitter", "exponential 1000*2^n, no jitter",
                "exponential, full jitter"};
        for (int m = 0; m < modes.length; m++) {
            Random r = new Random(7);
            TreeMap<Long, Integer> buckets = new TreeMap<>();
            for (int c = 0; c < 1000; c++) {
                long t = 0;
                for (int attempt = 0; attempt < 3; attempt++) {
                    long cap = m == 0 ? 1000 : 1000L << attempt;
                    long wait = m == 2 ? (long) (r.nextDouble() * cap) : cap;
                    t += wait;
                    buckets.merge(t / 250 * 250, 1, Integer::sum);
                }
            }
            int peak = buckets.values().stream().mapToInt(Integer::intValue).max().orElse(0);
            System.out.printf("%-34s buckets=%3d peak=%4d retries per 250 ms%n", modes[m],
                    buckets.size(), peak);
        }
        System.out.println();
    }

    public static void main(String[] args) {
        backoff();
        storm();
        herd();
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.concurrent.TimeoutException;

public class CircuitBreakerDemo {

    enum State { CLOSED, OPEN, HALF_OPEN }

    static class CallNotPermitted extends RuntimeException {
        CallNotPermitted() { super("circuit open", null, false, false); }
    }

    interface Call<T> { T run() throws Exception; }

    /** Count-based sliding window breaker, modelled on Resilience4j semantics. */
    static class Breaker {
        final int windowSize, minCalls, halfOpenPermits;
        final double failureRate;
        final long waitOpenMs;
        State state = State.CLOSED;
        final Deque<Boolean> window = new ArrayDeque<>(); // true = failure
        long openedAt;
        int halfOpenInFlight, halfOpenDone, halfOpenFailed;
        final long t0 = System.nanoTime();

        Breaker(int windowSize, int minCalls, double failureRate, long waitOpenMs,
                int halfOpenPermits) {
            this.windowSize = windowSize; this.minCalls = minCalls; this.failureRate = failureRate;
            this.waitOpenMs = waitOpenMs; this.halfOpenPermits = halfOpenPermits;
        }

        long now() { return (System.nanoTime() - t0) / 1_000_000; }

        void transition(State to, String why) {
            System.out.printf("t=%4d ms  %-9s -> %-9s  (%s)%n", now(), state, to, why);
            state = to;
            if (to == State.OPEN) openedAt = now();
            if (to == State.HALF_OPEN) {
                halfOpenInFlight = 0; halfOpenDone = 0; halfOpenFailed = 0;
            }
            if (to == State.CLOSED) window.clear();
        }

        <T> T execute(Call<T> c) throws Exception {
            if (state == State.OPEN) {
                if (now() - openedAt >= waitOpenMs) transition(State.HALF_OPEN, "wait elapsed");
                else throw new CallNotPermitted();
            }
            if (state == State.HALF_OPEN) {
                if (halfOpenInFlight >= halfOpenPermits) throw new CallNotPermitted();
                halfOpenInFlight++;
            }
            try {
                T r = c.run();
                record(false);
                return r;
            } catch (Exception e) {
                record(true);
                throw e;
            }
        }
        void record(boolean failure) {
            if (state == State.HALF_OPEN) {
                halfOpenDone++;
                if (failure) halfOpenFailed++;
                if (halfOpenDone == halfOpenPermits) {
                    double rate = 100.0 * halfOpenFailed / halfOpenDone;
                    if (rate >= failureRate) transition(State.OPEN, "probe failure rate " + rate
                            + "%");
                    else transition(State.CLOSED, "probe failure rate " + rate + "%");
                }
                return;
            }
            window.addLast(failure);
            if (window.size() > windowSize) window.removeFirst();
            if (window.size() >= minCalls) {
                long f = window.stream().filter(b -> b).count();
                double rate = 100.0 * f / window.size();
                if (rate >= failureRate) transition(State.OPEN, "failure rate " + rate + "% of "
                        + window.size());
            }
        }
    }

    static final long TIMEOUT_MS = 100;
    static long outageStart = 500, outageEnd = 2000;
    static int reached = 0;

    /** Simulated remote call: healthy 20 ms; during the outage it hangs for 400 ms,
            the client times out at 100 ms. */
    static String remote(long tNowMs) throws Exception {
        reached++;
        boolean down = tNowMs >= outageStart && tNowMs < outageEnd;
        long latency = down ? 400 : 20;
        Thread.sleep(Math.min(latency, TIMEOUT_MS));
        if (latency > TIMEOUT_MS) throw new TimeoutException("no response in " + TIMEOUT_MS
                + " ms");
        return "ok";
    }

    static void run(String title, boolean useBreaker) throws Exception {
        System.out.println("== " + title);
        Breaker cb = new Breaker(10, 5, 50.0, 1000, 3);
        reached = 0;
        int ok = 0, failed = 0, rejected = 0;
        long blocked = 0;
        long start = System.nanoTime();
        for (int i = 0; i < 70; i++) {
            long t = (System.nanoTime() - start) / 1_000_000;
            long c0 = System.nanoTime();
            try {
                if (useBreaker) cb.execute(() -> remote(t)); else remote(t);
                ok++;
            } catch (CallNotPermitted e) { rejected++;
            } catch (Exception e) { failed++; }
            blocked += (System.nanoTime() - c0) / 1_000_000;
            long wait = (i + 1) * 50L - (System.nanoTime() - start) / 1_000_000;
            if (wait > 0) Thread.sleep(wait);
        }
        System.out.printf(
                "calls=70 ok=%d timeout=%d rejected=%d  reached=%d  blocked=%d ms%n%n",
                ok, failed, rejected, reached, blocked);
    }

    public static void main(String[] a) throws Exception {
        run("without circuit breaker", false);
        run("with circuit breaker (window 10, min 5, 50%, wait 1000 ms, 3 probes)", true);
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

public class BulkheadDemo {

    static final int WORKERS = 10;          // stands in for the Tomcat worker pool
    static final long SLOW_MS = 800;        // latency of the degraded dependency
    static final Semaphore BULKHEAD = new Semaphore(4);

    static void scenario(String title, boolean bulkhead) throws Exception {
        ExecutorService workers = Executors.newFixedThreadPool(WORKERS);
        AtomicInteger rejected = new AtomicInteger();
        List<Future<Long>> fast = new ArrayList<>();
        // 30 requests to /orders (needs the slow dependency) arrive first
        for (int i = 0; i < 30; i++) {
            workers.submit(() -> {
                if (bulkhead && !BULKHEAD.tryAcquire()) { rejected.incrementAndGet(); return; }
                try { Thread.sleep(SLOW_MS); } catch (
                        InterruptedException e) { Thread.currentThread().interrupt(); }
                finally { if (bulkhead) BULKHEAD.release(); }
            });
        }
        Thread.sleep(50);
        // then 10 requests to /health-like endpoint that need no dependency (1 ms of work)
        for (int i = 0; i < 10; i++) {
            long enq = System.nanoTime();
            fast.add(workers.submit(() -> (System.nanoTime() - enq) / 1_000_000));
        }
        long max = 0, sum = 0;
        for (Future<Long> f : fast) { long v = f.get(); max = Math.max(max, v); sum += v; }
        System.out.printf(
                "%-24s fast endpoint: avg wait=%4d ms  max wait=%4d ms  slow calls rejected=%d%n",
                title, sum / fast.size(), max, rejected.get());
        workers.shutdownNow();
    }

    public static void main(String[] a) throws Exception {
        System.out.println("worker pool = " + WORKERS + " threads, dependency latency = "
                + SLOW_MS + " ms");
        scenario("no bulkhead", false);
        scenario("bulkhead (4 concurrent)", true);
    }
}

