        this.state = next;
        this.reached = next;
        this.updatedAt = Instant.now();
    }

    public void startCompensation(String reason) {
        this.state = SagaState.COMPENSATING;
        this.failureReason = reason;
        this.updatedAt = Instant.now();
    }

    public void cancelled() {
        this.state = SagaState.CANCELLED;
        this.updatedAt = Instant.now();
    }
