package com.shop.order.saga;

import com.shop.order.domain.Order;
import com.shop.order.domain.OrderRepository;
import com.shop.order.infrastructure.InventoryClient;
import com.shop.order.infrastructure.PaymentClient;
import com.shop.order.infrastructure.ShippingClient;
import java.util.UUID;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.dao.OptimisticLockingFailureException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;

@Service
public class CheckoutOrchestrator {

    private static final Logger log = LoggerFactory.getLogger(CheckoutOrchestrator.class);

    private final CheckoutSagaRepository sagas;
    private final OrderRepository orders;
    private final InventoryClient inventory;
    private final PaymentClient payments;
    private final ShippingClient shipping;
    private final TransactionTemplate tx;

    public CheckoutOrchestrator(CheckoutSagaRepository sagas, OrderRepository orders,
                                InventoryClient inventory, PaymentClient payments,
                                ShippingClient shipping, TransactionTemplate tx) {
        this.sagas = sagas;
        this.orders = orders;
        this.inventory = inventory;
        this.payments = payments;
        this.shipping = shipping;
        this.tx = tx;
    }

    /** Runs or resumes a saga. Each step is persisted before the next one starts. */
    public void run(UUID sagaId) {
        CheckoutSaga saga = sagas.findById(sagaId).orElseThrow();
        Order order = orders.findWithLinesById(saga.getOrderId()).orElseThrow();
        try {
            if (saga.getState() == SagaState.STARTED) {
                inventory.reserve(key(saga, "reserve"), InventoryClient.requestFor(order));
                saga = persist(saga, SagaState.STOCK_RESERVED);
            }
            if (saga.getState() == SagaState.STOCK_RESERVED) {
                payments.capture(key(saga, "pay"), PaymentClient.requestFor(order));
                saga = persist(saga, SagaState.PAYMENT_CAPTURED);
            }
            if (saga.getState() == SagaState.PAYMENT_CAPTURED) {
                shipping.create(key(saga, "ship"), ShippingClient.requestFor(order));
                saga = persist(saga, SagaState.SHIPMENT_CREATED);
            }
            if (saga.getState() == SagaState.SHIPMENT_CREATED) {
                final CheckoutSaga done = saga;
                tx.executeWithoutResult(s -> {
                    orders.findById(done.getOrderId()).orElseThrow().confirm();
                    CheckoutSaga fresh = sagas.findById(done.getId()).orElseThrow();
                    fresh.advance(SagaState.COMPLETED);
                });
            }
        } catch (OptimisticLockingFailureException e) {
            log.info("saga {} is being advanced by another instance", sagaId);
        } catch (RuntimeException e) {
            log.warn("saga {} failed in state {}: {}", sagaId, saga.getState(), e.toString());
            compensate(saga, e.getMessage());
        }
    }

    private void compensate(CheckoutSaga current, String reason) {
        final UUID sagaId = current.getId();
        final UUID orderId = current.getOrderId();
        CheckoutSaga saga = current;
        if (saga.getState() != SagaState.COMPENSATING) {
            saga = tx.execute(s -> {
                CheckoutSaga fresh = sagas.findById(sagaId).orElseThrow();
                fresh.startCompensation(reason);
                return fresh;
            });
        }
        // reverse order; every compensation is idempotent and is retried by the recovery job
        if (saga.getReached().atLeast(SagaState.PAYMENT_CAPTURED)) {
            payments.refund(key(saga, "refund"), orderId);
        }
        if (saga.getReached().atLeast(SagaState.STOCK_RESERVED)) {
            inventory.release(orderId);
        }
        tx.executeWithoutResult(s -> {
            orders.findById(orderId).orElseThrow().cancel();
            sagas.findById(sagaId).orElseThrow().cancelled();
        });
    }

    private CheckoutSaga persist(CheckoutSaga saga, SagaState next) {
        final UUID id = saga.getId();
        return tx.execute(s -> {
            CheckoutSaga fresh = sagas.findById(id).orElseThrow();
            fresh.advance(next);
            return fresh;
        });
    }

    private static String key(CheckoutSaga saga, String step) {
        return saga.getId() + ":" + step;
    }
}

