    /** MANDATORY: fails fast if called without a surrounding business transaction. */
    @Transactional(propagation = Propagation.MANDATORY)
    public void write(String aggregateType, String aggregateId, String eventType, Object event) {
        try {
            jdbc.sql("""
                INSERT INTO outbox (aggregate_type, aggregate_id, event_type, payload)
                VALUES (:type, :id, :event, CAST(:payload AS jsonb))
                """)
                .param("type", aggregateType)
                .param("id", aggregateId)
                .param("event", eventType)
                .param("payload", json.writeValueAsString(event))
                .update();
        } catch (JsonProcessingException e) {
            throw new IllegalArgumentException("cannot serialise " + eventType, e);
        }
    }
}

@Transactional
public Order place(UUID customerId, List<Item> items) {
    Order order = new Order(customerId);
    for (Item item : items) {
        order.addLine(item.sku(), item.quantity(), prices.priceOf(item.sku()));
    }
    orders.save(order);
    sagas.save(new CheckoutSaga(order.getId()));
    outbox.write("Order", order.getId().toString(), "OrderPlaced",
        new OrderPlaced(order.getId(), customerId, order.getTotal()));
    return order;
}

package com.shop.order.outbox;

import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.concurrent.TimeUnit;
import org.apache.kafka.clients.producer.ProducerRecord;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OutboxBatchPublisher {

    private static final Logger log = LoggerFactory.getLogger(OutboxBatchPublisher.class);

    record Row(long id, String aggregateType, String aggregateId, String eventType,
               String payload) { }

    private final JdbcClient jdbc;
    private final KafkaTemplate<String, String> kafka;

    public OutboxBatchPublisher(JdbcClient jdbc, KafkaTemplate<String, String> kafka) {
        this.jdbc = jdbc;
        this.kafka = kafka;
    }

    @Transactional
    public int publishPending() {
        List<Row> rows = jdbc.sql("""
            SELECT id, aggregate_type, aggregate_id, event_type, payload::text AS payload
            FROM outbox
            WHERE published_at IS NULL
            ORDER BY id
            LIMIT 100
            FOR UPDATE SKIP LOCKED
            """)
            .query((rs, n) -> new Row(rs.getLong("id"), rs.getString("aggregate_type"),
                rs.getString("aggregate_id"), rs.getString("event_type"), rs.getString("payload")))
            .list();
        int published = 0;
        for (Row row : rows) {
            ProducerRecord<String, String> record = new ProducerRecord<>(
                "order-events", row.aggregateId(), row.payload());
            record.headers().add("message-id",
                Long.toString(row.id()).getBytes(StandardCharsets.UTF_8));
            record.headers().add("event-type", row.eventType().getBytes(StandardCharsets.UTF_8));
            try {
                kafka.send(record).get(5, TimeUnit.SECONDS);
            } catch (Exception e) {
                log.warn("outbox row {} not published: {}", row.id(), e.toString());
                break;                      // keep per-aggregate order: stop, retry on the next run
            }
            jdbc.sql("UPDATE outbox SET published_at = now() WHERE id = :id")
                .param("id", row.id()).update();
            published++;
        }
        return published;
    }
}

package com.shop.order.outbox;

import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

@Component
public class OutboxRelay {

    private final OutboxBatchPublisher publisher;

    public OutboxRelay(OutboxBatchPublisher publisher) {
        this.publisher = publisher;
    }

    @Scheduled(fixedDelayString = "PT0.5S")
    public void run() {
        while (publisher.publishPending() > 0) {
            // drain the backlog before sleeping again
        }
    }
}

package com.shop.shipping;

import java.nio.charset.StandardCharsets;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

@Component
public class PaymentEventsListener {

    private final JdbcClient jdbc;
    private final ShipmentService shipments;

    public PaymentEventsListener(JdbcClient jdbc, ShipmentService shipments) {
        this.jdbc = jdbc;
        this.shipments = shipments;
    }

    @KafkaListener(topics = "payment-events", groupId = "shipping-service")
    @Transactional
    public void onEvent(ConsumerRecord<String, String> record) {
        String messageId = new String(record.headers().lastHeader("message-id").value(),
            StandardCharsets.UTF_8);
        int claimed = jdbc.sql("""
            INSERT INTO processed_messages (message_id, consumer)
            VALUES (:id, 'shipping-service')
            ON CONFLICT DO NOTHING
            """).param("id", messageId).update();
        if (claimed == 0) {
            return;                     // duplicate delivery: already processed
        }
        shipments.handlePaymentEvent(record.key(), record.value());
    }
}

import java.util.*;

public class SagaDemo {

    // ---- in-memory "services" -------------------------------------------------------------
    static final Map<String, String> orders = new LinkedHashMap<>();
    static int stock = 5;
    static int chargedCents = 0;
    // idempotency store of the payment service
    static final Set<String> processedKeys = new HashSet<>();
    static boolean shippingDown = false;
    static int paymentCalls = 0;

    static void createOrder(String id) { orders.put(id, "PENDING"); }
    static void cancelOrder(String id) { orders.put(id, "CANCELLED"); }
    static void approveOrder(String id) { orders.put(id, "CONFIRMED"); }
    static void reserve(int qty) { if (stock < qty) throw new IllegalStateException(
            "out of stock"); stock -= qty; }
    static void release(int qty) { stock += qty; }
    static void charge(String key, int cents) {
        paymentCalls++;
        if (!processedKeys.add(key)) { System.out.println("    payment: duplicate key " + key
                + ", ignored"); return; }
        chargedCents += cents;
    }
    static void refund(String key, int cents) {
        if (processedKeys.add("refund-" + key)) chargedCents -= cents;
    }
    static void ship(String id) { if (shippingDown) throw new IllegalStateException(
            "shipping unavailable"); }

    interface Action { void run(); }
    record Step(String name, Action action, Action compensation) {}

    static void runSaga(String orderId, List<Step> steps) {
        Deque<Step> done = new ArrayDeque<>();
        try {
            for (Step s : steps) {
                System.out.println("  do   " + s.name());
                s.action().run();
                done.push(s);
            }
            approveOrder(orderId);
            System.out.println("  saga completed");
        } catch (RuntimeException e) {
            System.out.println("  FAILED: " + e.getMessage() + " -> compensating " + done.size()
                    + " step(s)");
            while (!done.isEmpty()) {
                Step s = done.pop();
                System.out.println("  undo " + s.name());
                s.compensation().run();
            }
            cancelOrder(orderId);
        }
    }

    static List<Step> checkout(String id, int qty, int cents) {
        return List.of(
                new Step("create order " + id, () -> createOrder(id), () -> {}),
                new Step("reserve stock x" + qty, () -> reserve(qty), () -> release(qty)),
                new Step("charge " + cents + " cents", () -> charge("pay-" + id, cents), ()
                        -> refund("pay-" + id, cents)),
                new Step("create shipment", () -> ship(id), () -> {}));
    }

    static void state(String label) {
        System.out.printf("  state [%s]: orders=%s stock=%d charged=%d%n", label, orders, stock,
                chargedCents);
    }

    public static void main(String[] args) {
        System.out.println("== A: no saga, shipping fails after payment (partial failure)");
        shippingDown = true;
        try { createOrder("o-1"); reserve(1); charge("pay-o-1", 4999); ship("o-1"); }
        catch (RuntimeException e) { System.out.println("  exception: " + e.getMessage()); }
        state("after");

        System.out.println("== B: orchestrated saga, same failure");
        orders.clear(); stock = 5; chargedCents = 0; processedKeys.clear();
        runSaga("o-2", checkout("o-2", 1, 4999));
        state("after");

        System.out.println("== C: saga, everything healthy");
        shippingDown = false;
        runSaga("o-3", checkout("o-3", 2, 1500));
        state("after");

        System.out.println("== D: payment request retried with the same idempotency key");
        int before = chargedCents, callsBefore = paymentCalls;
        charge("pay-o-4", 700); charge("pay-o-4", 700); charge("pay-o-4", 700);
        System.out.println("  requests received=" + (paymentCalls - callsBefore)
                + ", amount charged=" + (chargedCents - before) + " cents");
    }
}
